import{_ as e,o as l,c as i,ai as r}from"./chunks/framework.ampVZV4B.js";const b=JSON.parse('{"title":"Python 面试 · 实战场景题","description":"","frontmatter":{},"headers":[],"relativePath":"guide/python/scenario-interview.md","filePath":"guide/python/scenario-interview.md"}'),o={name:"guide/python/scenario-interview.md"};function t(n,a,h,s,c,d){return l(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="python-面试-·-实战场景题" tabindex="-1">Python 面试 · 实战场景题 <a class="header-anchor" href="#python-面试-·-实战场景题" aria-label="Permalink to “Python 面试 · 实战场景题”">​</a></h1><blockquote><p>白板/口述：「给你一个活，你怎么写脚本？」按步骤答。</p></blockquote><hr><h2 id="答题骨架" tabindex="-1">答题骨架 <a class="header-anchor" href="#答题骨架" aria-label="Permalink to “答题骨架”">​</a></h2><ol><li>输入输出与成功标准</li><li>同步还是并发</li><li>超时、重试、限流</li><li>失败怎么记、怎么重跑</li><li>要不要换成 Java 长期服务</li></ol><hr><h2 id="题-a-批量调模型-api-做摘要" tabindex="-1">题 A：批量调模型 API 做摘要 <a class="header-anchor" href="#题-a-批量调模型-api-做摘要" aria-label="Permalink to “题 A：批量调模型 API 做摘要”">​</a></h2><p><strong>要点：</strong></p><ul><li>读任务列表 → 逐条/并发请求 → 写结果 JSON/CSV</li><li><code>timeout</code> + 指数退避重试；429 要降速</li><li>并发用线程池，设最大并发，避免把 Key 限流打爆</li><li>失败行单独记错误文件，支持断点续跑</li></ul><hr><h2 id="题-b-读-2gb-日志-统计错误码-top-n" tabindex="-1">题 B：读 2GB 日志，统计错误码 Top N <a class="header-anchor" href="#题-b-读-2gb-日志-统计错误码-top-n" aria-label="Permalink to “题 B：读 2GB 日志，统计错误码 Top N”">​</a></h2><p><strong>要点：</strong></p><ul><li>别 <code>read()</code> 全进内存；逐行迭代或分块</li><li>用字典计数；若还太大，考虑外排序/分片</li><li>编码问题：<code>errors=&#39;replace&#39;</code> 或先探查编码</li></ul><hr><h2 id="题-c-设备临时采集脚本-modbus-http-上报" tabindex="-1">题 C：设备临时采集脚本（Modbus/HTTP 上报） <a class="header-anchor" href="#题-c-设备临时采集脚本-modbus-http-上报" aria-label="Permalink to “题 C：设备临时采集脚本（Modbus/HTTP 上报）”">​</a></h2><p><strong>要点：</strong></p><ul><li>连接失败重试、断开重连</li><li>采样周期用 sleep/调度；异常不能让脚本静默退出无日志</li><li>与正式 Gateway 的边界：脚本是验证/应急，生产采集仍走稳定服务（可接 Java/Node）</li></ul><hr><h2 id="题-d-把-excel-csv-清洗后入库" tabindex="-1">题 D：把 Excel/CSV 清洗后入库 <a class="header-anchor" href="#题-d-把-excel-csv-清洗后入库" aria-label="Permalink to “题 D：把 Excel/CSV 清洗后入库”">​</a></h2><p><strong>要点：</strong></p><ul><li>pandas 或 csv 模块；类型与空值处理</li><li>先校验再入库；批量 insert；事务或分批提交</li><li>密钥与 DB 连接配置环境变量化</li></ul><hr><h2 id="题-e-简单定时任务" tabindex="-1">题 E：简单定时任务 <a class="header-anchor" href="#题-e-简单定时任务" aria-label="Permalink to “题 E：简单定时任务”">​</a></h2><p><strong>要点：</strong></p><ul><li>本机可用系统 crontab / 计划任务跑脚本</li><li>业务级定时更常见用 Java（XXL-JOB 等）；Python 脚本适合边缘小任务</li><li>说明你会<strong>选型</strong>，不是什么都塞 Python</li></ul><hr><h2 id="收尾金句" tabindex="-1">收尾金句 <a class="header-anchor" href="#收尾金句" aria-label="Permalink to “收尾金句”">​</a></h2><blockquote><p>「脚本先保证可观测和可重跑；活稳定了再决定要不要升成长期服务。」</p></blockquote>',28)])])}const u=e(o,[["render",t]]);export{b as __pageData,u as default};
